CREATE OR REPLACE FUNCTION platform_private.delivery_merge_split_20261030(p_item uuid, p_ctx jsonb, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_s public.estoque_produto%ROWTYPE; v_main public.estoque_produto%ROWTYPE;
 v_ent uuid:=NULLIF(p_payload->>'referencia_id','')::uuid; v_total numeric; v_volume numeric;
BEGIN
 v_org:=platform_private.delivery_actor_20261030('cancel');
 IF NOT EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND organization_id=v_org AND action='cancel' AND target=v_ent AND NOT consumed)
 OR NOT EXISTS(SELECT 1 FROM platform_private.stock_motor_context WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND item=p_item AND ctx=p_ctx AND ctx->>'acao'='cancelamento_reserva')
 THEN RAISE EXCEPTION 'DELIVERY_MERGE_CONTEXT_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_s FROM public.estoque_produto WHERE id=p_item FOR UPDATE;
 PERFORM platform_private.stock_motor_item(p_item,'cancelamento_reserva',p_payload);
 IF v_s.status::text<>'reservado' OR v_s.quantidade IS DISTINCT FROM v_s.quantidade_reservada OR v_s.quantidade IS NULL OR v_s.quantidade<=0 OR v_s.quantidade::text IN ('NaN','Infinity','-Infinity') OR v_s.volume_total IS NULL OR v_s.volume_total<=0 OR v_s.volume_total::text IN ('NaN','Infinity','-Infinity') OR NOT EXISTS(SELECT 1 FROM public.entregas WHERE id=v_ent AND organization_id=v_org AND estoque_produto_id=p_item AND quantidade_entregue=v_s.quantidade) THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 SELECT * INTO v_main FROM public.estoque_produto WHERE lote_id=v_s.lote_id AND status='disponivel' AND coalesce(quantidade_reservada,0)=0 AND id<>p_item ORDER BY id LIMIT 1 FOR UPDATE;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 IF v_main.id IS NULL THEN
  UPDATE public.estoque_produto SET status='disponivel' WHERE id=p_item;
  RETURN;
 END IF;
 PERFORM platform_private.stock_motor_item(v_main.id,'cancelamento_reserva','{}'::jsonb);
 IF v_main.envase_id IS DISTINCT FROM v_s.envase_id OR v_main.produto_id IS DISTINCT FROM v_s.produto_id OR v_main.microrganismo_id IS DISTINCT FROM v_s.microrganismo_id OR v_main.validade IS DISTINCT FROM v_s.validade OR v_main.reservado_para_os_id IS NOT NULL OR v_main.reservado_para_cliente_id IS NOT NULL OR v_main.reservado_para_partner_id IS NOT NULL OR v_main.reservado_para_partner_order_id IS NOT NULL THEN RAISE EXCEPTION 'DELIVERY_MERGE_INCOMPATIBLE' USING ERRCODE='PT409'; END IF;
 IF v_main.quantidade IS NULL OR v_main.quantidade<=0 OR v_main.quantidade::text IN ('NaN','Infinity','-Infinity') OR v_main.volume_total IS NULL OR v_main.volume_total<=0 OR v_main.volume_total::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 v_total:=v_main.quantidade+v_s.quantidade; v_volume:=v_main.volume_total+v_s.volume_total;
 IF v_total IS NULL OR v_volume IS NULL OR v_total<=0 OR v_volume<=0 OR v_total::text IN ('NaN','Infinity','-Infinity') OR v_volume::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 -- Keep source row and immutable movement history; retire it BEFORE growing the unique main row.
 UPDATE public.estoque_produto SET status='estornado',quantidade=0,volume_total=0,quantidade_reservada=0,reservado_para_os_id=NULL,reservado_para_os_tipo=NULL,reservado_para_cliente_id=NULL,reservado_para_partner_id=NULL,reservado_para_partner_order_id=NULL WHERE id=p_item;
 UPDATE public.estoque_produto SET quantidade=v_total,volume_total=v_volume WHERE id=v_main.id;
 IF NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE estoque_produto_id=p_item AND idempotency_key=p_ctx->>'idempotency_key' AND saldo_posterior=0 AND acao='cancelamento_reserva')
 OR NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE estoque_produto_id=v_main.id AND metadata->>'operacao_key'=p_ctx->>'idempotency_key' AND saldo_anterior=v_main.quantidade AND saldo_posterior=v_total AND volume_posterior=v_volume AND acao='cancelamento_reserva')
 THEN RAISE EXCEPTION 'DELIVERY_MERGE_LEDGER_DENIED' USING ERRCODE='PT409'; END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.entregas_catalog_tenant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_t uuid;
BEGIN
  IF NOT (NEW.produto_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF true THEN
    v_t := platform_private.catalog_tenant_agree(ARRAY[(NEW.organization_id)::uuid, ((SELECT o.organization_id FROM public.ordens_servico o WHERE o.id = NEW.ordem_servico_id))::uuid, ((SELECT l.organization_id FROM public.lotes l WHERE l.id = NEW.lote_id))::uuid, ((SELECT pa.commercial_owner_organization_id FROM public.partner_accounts pa WHERE pa.id = (SELECT po.partner_id FROM public.partner_orders po WHERE po.id = NEW.partner_order_id)))::uuid, ((SELECT cl.organization_id FROM public.clientes cl WHERE cl.id = NEW.cliente_id))::uuid]);
    IF NEW.produto_id IS NOT NULL AND (v_t IS NULL OR NOT EXISTS (SELECT 1 FROM public.produtos z WHERE z.id = NEW.produto_id AND z.owner_organization_id = v_t)) THEN
      RAISE EXCEPTION 'tenant_catalog_cross_tenant_reference' USING ERRCODE = '42501', DETAIL = 'entregas.produto_id'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.envase_insert_final_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p platform_private.envase_insert_permits_v1%ROWTYPE;
BEGIN
 DELETE FROM platform_private.envase_insert_permits_v1 WHERE txid=txid_current() AND actor=auth.uid() AND action=TG_TABLE_NAME AND target=NEW.id AND admitted RETURNING * INTO p;
 IF FOUND THEN
  IF p.organization_id IS DISTINCT FROM platform_private.stock_envase_scope_v1(p.lote,p.prog,p.os,'manual')
   OR (to_jsonb(NEW)-'created_at'-'updated_at') IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'ENVASE_FINAL_PERMIT_MISMATCH' USING ERRCODE='42501'; END IF;
 ELSIF TG_TABLE_NAME='envase' THEN RAISE EXCEPTION 'ENVASE_FINAL_PERMIT_MISSING' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.envase_insert_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p platform_private.envase_insert_permits_v1%ROWTYPE; c record; parent public.estoque_produto%ROWTYPE; a jsonb; org uuid;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'ENVASE_ISOLATION_UNSUPPORTED' USING ERRCODE='0A000'; END IF;
 UPDATE platform_private.envase_insert_permits_v1 SET admitted=true WHERE txid=txid_current() AND actor=auth.uid() AND action=TG_TABLE_NAME AND target=NEW.id AND admitted=false RETURNING * INTO p;
 IF FOUND THEN
  IF p.organization_id IS DISTINCT FROM platform_private.stock_envase_scope_v1(p.lote,p.prog,p.os,'manual')
   OR NEW.lote_id IS DISTINCT FROM p.lote OR (to_jsonb(NEW)-'created_at'-'updated_at') IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'ENVASE_INSERT_PERMIT_MISMATCH' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 -- Preserve ONLY the installed canonical partial reservation semantics under
 -- its private txid/actor/parent context, not an invented envase permit.
 IF TG_TABLE_NAME='estoque_produto' THEN
  SELECT * INTO c FROM platform_private.stock_motor_context WHERE txid=txid_current() AND actor=auth.uid();
  IF FOUND AND c.ctx->>'acao'='reserva' AND c.item IS NOT NULL AND NEW.id<>c.item THEN
   SELECT * INTO parent FROM public.estoque_produto WHERE id=c.item;
   a:=c.ctx->'reserve_args'; org:=platform_private.stock_motor_actor('reserva');
   IF parent.status::text='disponivel' AND NEW.status::text='reservado' AND NEW.quantidade>0 AND NEW.quantidade<parent.quantidade
    AND NEW.quantidade_reservada=NEW.quantidade AND NEW.lote_id=parent.lote_id
    AND NEW.envase_id IS NOT DISTINCT FROM parent.envase_id AND NEW.produto_id IS NOT DISTINCT FROM parent.produto_id AND NEW.microrganismo_id IS NOT DISTINCT FROM parent.microrganismo_id
    AND NEW.validade IS NOT DISTINCT FROM parent.validade AND NEW.volume_total=NEW.quantidade*parent.volume_total/parent.quantidade
    AND NEW.reservado_para_os_id::text IS NOT DISTINCT FROM a->>'os_id' AND NEW.reservado_para_os_tipo IS NOT DISTINCT FROM a->>'os_tipo'
    AND NEW.reservado_para_cliente_id::text IS NOT DISTINCT FROM a->>'cliente_id'
    AND NEW.reservado_para_partner_id::text IS NOT DISTINCT FROM a->>'partner_id' AND NEW.reservado_para_partner_order_id::text IS NOT DISTINCT FROM a->>'partner_order_id'
    AND NEW.observacao_reserva IS NOT DISTINCT FROM a->>'observacao'
    AND EXISTS(SELECT 1 FROM public.lotes WHERE id=parent.lote_id AND organization_id=org) THEN RETURN NEW; END IF;
  END IF;
 END IF;
 RAISE EXCEPTION 'ENVASE_INSERT_CLOSED' USING ERRCODE='42501';
END $function$

CREATE OR REPLACE FUNCTION platform_private.estoque_produto_catalog_tenant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_t uuid;
BEGIN
  IF NOT (NEW.produto_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF true THEN
    v_t := (SELECT l.organization_id FROM public.lotes l WHERE l.id = NEW.lote_id);
    IF NEW.produto_id IS NOT NULL AND (v_t IS NULL OR NOT EXISTS (SELECT 1 FROM public.produtos z WHERE z.id = NEW.produto_id AND z.owner_organization_id = v_t)) THEN
      RAISE EXCEPTION 'tenant_catalog_cross_tenant_reference' USING ERRCODE = '42501', DETAIL = 'estoque_produto.produto_id'; END IF;
    IF NEW.microrganismo_id IS NOT NULL AND (v_t IS NULL OR NOT EXISTS (SELECT 1 FROM public.microrganismos z WHERE z.id = NEW.microrganismo_id AND z.owner_organization_id = v_t)) THEN
      RAISE EXCEPTION 'tenant_catalog_cross_tenant_reference' USING ERRCODE = '42501', DETAIL = 'estoque_produto.microrganismo_id'; END IF;
  END IF;
  RETURN NEW;
END $function$

